using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor;using UnityEditor.SceneManagement;using DeliveryRider;
public static class MyeongjiLightingPreview {
 public static string Render(){if(EditorApplication.isPlaying)throw new Exception("Edit only");var scene=SceneManager.GetActiveScene();var sky=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<DaySky>(true)).Single();var original=RenderSettings.skybox;var field=typeof(DaySky).GetField("sky",BindingFlags.Instance|BindingFlags.NonPublic);var strength=typeof(DaySky).GetField("shadowStrength",BindingFlags.Instance|BindingFlags.NonPublic);var temp=new Material(original){hideFlags=HideFlags.HideAndDontSave};var host=new GameObject("Temporary_Lighting_Preview");var cam=host.AddComponent<Camera>();var rt=new RenderTexture(1280,720,24);Texture2D image=null;var previous=RenderTexture.active;var oldField=field.GetValue(sky);var oldStrength=strength.GetValue(sky);
 try{field.SetValue(sky,temp);strength.SetValue(sky,.9f);RenderSettings.skybox=temp;sky.Apply(.9f,0);cam.transform.position=new Vector3(27,3.2f,-43);cam.transform.LookAt(new Vector3(39,5,-14));cam.fieldOfView=65;cam.nearClipPlane=.1f;cam.farClipPlane=300;cam.clearFlags=CameraClearFlags.Skybox;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();string path="C:/Users/PC/Documents/Codex/Myeongji_District/Lighting_Sunset_20261103.png";File.WriteAllBytes(path,image.EncodeToPNG());return path;}
 finally{sky.Apply(0,0);field.SetValue(sky,oldField);strength.SetValue(sky,oldStrength);RenderSettings.skybox=original;RenderTexture.active=previous;cam.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);if(image!=null)UnityEngine.Object.DestroyImmediate(image);UnityEngine.Object.DestroyImmediate(host);UnityEngine.Object.DestroyImmediate(temp);sky.Sun.shadowStrength=.9f;EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}
